-- ============================================================
-- SKILLLENS FULL INITIAL SEED v12 - MINAT BIDANG + ROADMAP LENGKAP
-- Dibuat untuk setup awal database SkillLens.
-- Fokus revisi:
-- 1) Minat bukan lagi sekadar hobi, tetapi bidang tujuan: Kuliah - X, Kerja - Y, Wirausaha - Z.
-- 2) Hobi diperbanyak dari umum sampai spesifik.
-- 3) Bakat dibuat umum dan realistis untuk konteks siswa Indonesia.
-- 4) Pengalaman diperbanyak: magang/PKL, part-time, jualan pasar, organisasi, freelance, proyek.
-- 5) Bobot jelas per jalur dan kelompok sekolah.
-- 6) Roadmap otomatis ada untuk SETIAP alternative aktif, 5 step + 2 detail per step.
-- Catatan: jalankan pada database kosong/setup awal. Jangan jalankan di produksi yang sudah punya data siswa.
-- ============================================================
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET collation_connection = utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=0;



CREATE TABLE IF NOT EXISTS metadata (
  `key` VARCHAR(100) PRIMARY KEY,
  `value` LONGTEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS source_references (
  id INT AUTO_INCREMENT PRIMARY KEY,
  source_key VARCHAR(80) NOT NULL UNIQUE,
  judul VARCHAR(255) NOT NULL,
  penerbit VARCHAR(160) NOT NULL,
  url VARCHAR(500) NOT NULL,
  cakupan VARCHAR(255) NOT NULL,
  catatan TEXT NULL,
  is_active TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dataset_source_map (
  id INT AUTO_INCREMENT PRIMARY KEY,
  data_type VARCHAR(50) NOT NULL,
  source_key VARCHAR(80) NOT NULL,
  fungsi VARCHAR(255) NOT NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  UNIQUE KEY uq_dataset_source_map (data_type, source_key),
  CONSTRAINT fk_dataset_source_map_source FOREIGN KEY (source_key) REFERENCES source_references(source_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS alternatives (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tujuan_karir VARCHAR(30) NOT NULL,
  nama VARCHAR(255) NOT NULL,
  kategori VARCHAR(50) NOT NULL,
  profil_tag_json JSON NOT NULL,
  akademik_json JSON NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT NOT NULL DEFAULT 1,
  UNIQUE KEY uq_alternatives (tujuan_karir, nama),
  KEY idx_alternatives_tujuan (tujuan_karir, is_active, sort_order),
  KEY idx_alternatives_kategori (kategori)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS weight_profiles (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tujuan_karir VARCHAR(30) NOT NULL,
  school_group VARCHAR(30) NOT NULL,
  deskripsi VARCHAR(255),
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT NOT NULL DEFAULT 1,
  UNIQUE KEY uq_weight_profiles (tujuan_karir, school_group)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS criteria_weights (
  id INT AUTO_INCREMENT PRIMARY KEY,
  profile_id INT NOT NULL,
  criterion VARCHAR(50) NOT NULL,
  weight DOUBLE NOT NULL,
  UNIQUE KEY uq_criteria_weights (profile_id, criterion),
  CONSTRAINT fk_criteria_weights_profile FOREIGN KEY (profile_id) REFERENCES weight_profiles(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS source_tag_weights (
  sumber VARCHAR(30) PRIMARY KEY,
  weight DOUBLE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tag_category_scores (
  mapped_key VARCHAR(120) PRIMARY KEY,
  sains DOUBLE NOT NULL,
  teknologi DOUBLE NOT NULL,
  sosial DOUBLE NOT NULL,
  bisnis DOUBLE NOT NULL,
  kreatif DOUBLE NOT NULL,
  praktik DOUBLE NOT NULL,
  agama DOUBLE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tag_similarity_groups (
  id INT AUTO_INCREMENT PRIMARY KEY,
  group_name VARCHAR(100) NOT NULL,
  mapped_keys_json JSON NOT NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  UNIQUE KEY uq_tag_similarity_groups_name (group_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS master_tags (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tipe ENUM('minat','bakat','hobi','pengalaman','prestasi') NOT NULL,
  label VARCHAR(255) NOT NULL,
  mapped_key VARCHAR(120) NOT NULL,
  kategori_hint ENUM('sains','teknologi','sosial','bisnis','kreatif','praktik','agama') NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT NOT NULL DEFAULT 1,
  UNIQUE KEY uq_master_tags (tipe, label),
  KEY idx_master_tags_tipe (tipe, is_active, sort_order),
  KEY idx_master_tags_mapped_key (mapped_key),
  KEY idx_master_tags_kategori (kategori_hint)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roadmap_master (
  id_roadmap INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  category VARCHAR(120) NULL,
  target_type ENUM('kuliah','kerja','wirausaha','umum') NOT NULL DEFAULT 'umum',
  recommended_for VARCHAR(120) NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_master_active (is_active),
  KEY idx_roadmap_master_target (target_type),
  KEY idx_roadmap_master_category (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roadmap_step (
  id_roadmap_step INT AUTO_INCREMENT PRIMARY KEY,
  id_roadmap INT NOT NULL,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  step_order INT NOT NULL DEFAULT 1,
  estimated_duration VARCHAR(80) NULL,
  output_target VARCHAR(180) NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_step_master (id_roadmap, step_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS roadmap_step_detail (
  id_roadmap_step_detail INT AUTO_INCREMENT PRIMARY KEY,
  id_roadmap_step INT NOT NULL,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  reference_link TEXT NULL,
  reference_type VARCHAR(80) NULL,
  detail_order INT NOT NULL DEFAULT 1,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_step_detail_step (id_roadmap_step, detail_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS prestasi_level_weights (
  level_key VARCHAR(80) PRIMARY KEY,
  label VARCHAR(160) NOT NULL,
  weight DOUBLE NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS prestasi_rank_weights (
  rank_key VARCHAR(80) PRIMARY KEY,
  label VARCHAR(160) NOT NULL,
  weight DOUBLE NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS prestasi_type_weights (
  type_key VARCHAR(120) PRIMARY KEY,
  label VARCHAR(180) NOT NULL,
  mapped_key VARCHAR(120) NOT NULL,
  kategori_hint ENUM('sains','teknologi','sosial','bisnis','kreatif','praktik','agama') NOT NULL,
  weight DOUBLE NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



-- Bersihkan seed agar tidak menumpuk. Aman untuk setup awal, bukan produksi.
TRUNCATE TABLE roadmap_step_detail;
TRUNCATE TABLE roadmap_step;
TRUNCATE TABLE roadmap_master;
TRUNCATE TABLE criteria_weights;
TRUNCATE TABLE weight_profiles;
TRUNCATE TABLE dataset_source_map;
TRUNCATE TABLE source_references;
TRUNCATE TABLE source_tag_weights;
TRUNCATE TABLE tag_category_scores;
TRUNCATE TABLE tag_similarity_groups;
TRUNCATE TABLE master_tags;
TRUNCATE TABLE alternatives;
TRUNCATE TABLE prestasi_level_weights;
TRUNCATE TABLE prestasi_rank_weights;
TRUNCATE TABLE prestasi_type_weights;
TRUNCATE TABLE metadata;


ON DUPLICATE KEY UPDATE `value`=VALUES(`value`);

ON DUPLICATE KEY UPDATE source_key=VALUES(source_key), judul=VALUES(judul), penerbit=VALUES(penerbit), url=VALUES(url), cakupan=VALUES(cakupan), catatan=VALUES(catatan), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE data_type=VALUES(data_type), source_key=VALUES(source_key), fungsi=VALUES(fungsi), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE sumber=VALUES(sumber), weight=VALUES(weight);

ON DUPLICATE KEY UPDATE level_key=VALUES(level_key), label=VALUES(label), weight=VALUES(weight), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE rank_key=VALUES(rank_key), label=VALUES(label), weight=VALUES(weight), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE type_key=VALUES(type_key), label=VALUES(label), mapped_key=VALUES(mapped_key), kategori_hint=VALUES(kategori_hint), weight=VALUES(weight), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE deskripsi=VALUES(deskripsi), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE profile_id=VALUES(profile_id), criterion=VALUES(criterion), weight=VALUES(weight);

ON DUPLICATE KEY UPDATE tipe=VALUES(tipe), label=VALUES(label), mapped_key=VALUES(mapped_key), kategori_hint=VALUES(kategori_hint), sort_order=VALUES(sort_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE tipe=VALUES(tipe), label=VALUES(label), mapped_key=VALUES(mapped_key), kategori_hint=VALUES(kategori_hint), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE mapped_key=VALUES(mapped_key), sains=VALUES(sains), teknologi=VALUES(teknologi), sosial=VALUES(sosial), bisnis=VALUES(bisnis), kreatif=VALUES(kreatif), praktik=VALUES(praktik), agama=VALUES(agama);
ON DUPLICATE KEY UPDATE mapped_key=VALUES(mapped_key), sains=VALUES(sains), teknologi=VALUES(teknologi), sosial=VALUES(sosial), bisnis=VALUES(bisnis), kreatif=VALUES(kreatif), praktik=VALUES(praktik), agama=VALUES(agama);

ON DUPLICATE KEY UPDATE group_name=VALUES(group_name), mapped_keys_json=VALUES(mapped_keys_json), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE kategori=VALUES(kategori), profil_tag_json=VALUES(profil_tag_json), akademik_json=VALUES(akademik_json), sort_order=VALUES(sort_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE kategori=VALUES(kategori), profil_tag_json=VALUES(profil_tag_json), akademik_json=VALUES(akademik_json), sort_order=VALUES(sort_order), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), category=VALUES(category), target_type=VALUES(target_type), recommended_for=VALUES(recommended_for), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), category=VALUES(category), target_type=VALUES(target_type), recommended_for=VALUES(recommended_for), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), step_order=VALUES(step_order), estimated_duration=VALUES(estimated_duration), output_target=VALUES(output_target), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), step_order=VALUES(step_order), estimated_duration=VALUES(estimated_duration), output_target=VALUES(output_target), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), step_order=VALUES(step_order), estimated_duration=VALUES(estimated_duration), output_target=VALUES(output_target), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), step_order=VALUES(step_order), estimated_duration=VALUES(estimated_duration), output_target=VALUES(output_target), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), reference_link=VALUES(reference_link), reference_type=VALUES(reference_type), detail_order=VALUES(detail_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), reference_link=VALUES(reference_link), reference_type=VALUES(reference_type), detail_order=VALUES(detail_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), reference_link=VALUES(reference_link), reference_type=VALUES(reference_type), detail_order=VALUES(detail_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), reference_link=VALUES(reference_link), reference_type=VALUES(reference_type), detail_order=VALUES(detail_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), reference_link=VALUES(reference_link), reference_type=VALUES(reference_type), detail_order=VALUES(detail_order), is_active=VALUES(is_active);
ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), reference_link=VALUES(reference_link), reference_type=VALUES(reference_type), detail_order=VALUES(detail_order), is_active=VALUES(is_active);


-- ============================================================
-- Validasi cepat setelah import
-- ============================================================
SELECT 'alternatives' AS table_name, COUNT(*) AS total FROM alternatives
UNION ALL SELECT 'master_tags', COUNT(*) FROM master_tags
UNION ALL SELECT 'roadmap_master', COUNT(*) FROM roadmap_master
UNION ALL SELECT 'roadmap_step', COUNT(*) FROM roadmap_step
UNION ALL SELECT 'roadmap_step_detail', COUNT(*) FROM roadmap_step_detail
UNION ALL SELECT 'weight_profiles', COUNT(*) FROM weight_profiles
UNION ALL SELECT 'criteria_weights', COUNT(*) FROM criteria_weights;

-- Cek jika ada alternative aktif yang belum punya roadmap
SELECT a.tujuan_karir, a.nama
FROM alternatives a
LEFT JOIN roadmap_master r
  ON r.target_type=a.tujuan_karir
 AND r.recommended_for=a.nama
 AND r.is_active=1
WHERE a.is_active=1 AND r.id_roadmap IS NULL;

SET FOREIGN_KEY_CHECKS=1;
-- SELESAI: 163 alternatives, 504 master_tags, 163 roadmap, 815 steps, 1630 detail.
